package config

import (
	"fmt"
	"sort"

	"gopkg.in/yaml.v3"
)

// Kind tells who owns a layer.
type Kind string

const (
	// KindManaged layers are generated by Twinnel; the UI only toggles them.
	KindManaged Kind = "managed"
	// KindUser layers are written by the user.
	KindUser Kind = "user"
)

// Stage fixes where a layer runs in the pipeline. Compose sorts layers by
// stage (stable, so the order inside a stage is kept):
//
//	subscription → base → user layers → tailscale coexist → leak guard
type Stage int

const (
	StageBase    Stage = iota // local ports, DNS, TUN, controller, UI
	StageUser                 // user overrides, in the given order
	StageCoexist              // managed Tailscale coexistence
	StageGuard                // managed leak guard, always last
)

func (s Stage) String() string {
	switch s {
	case StageBase:
		return "base"
	case StageUser:
		return "user"
	case StageCoexist:
		return "coexist"
	case StageGuard:
		return "guard"
	}
	return fmt.Sprintf("stage(%d)", int(s))
}

// Transform edits the composed document in place and may return warnings.
type Transform func(root *yaml.Node) (warnings []string, err error)

// Layer is one override step.
type Layer struct {
	ID      string
	Name    string
	Kind    Kind
	Stage   Stage
	Enabled bool
	// Override is a YAML override in the Merge syntax. May be empty.
	Override []byte
	// Transform, if set, runs after Override is merged.
	Transform Transform
}

// Result is the outcome of a composition.
type Result struct {
	Config   []byte
	Applied  []string // IDs of the layers that ran, in order
	Warnings []string
}

// Compose builds the final configuration from a subscription and layers.
// Disabled layers are skipped.
func Compose(subscription []byte, layers []Layer) ([]byte, error) {
	r, err := ComposeReport(subscription, layers)
	if err != nil {
		return nil, err
	}
	return r.Config, nil
}

// ComposeReport is Compose with the list of applied layers and warnings.
func ComposeReport(subscription []byte, layers []Layer) (*Result, error) {
	root, err := Parse(subscription)
	if err != nil {
		return nil, fmt.Errorf("subscription: %w", err)
	}
	ordered := make([]Layer, len(layers))
	copy(ordered, layers)
	sort.SliceStable(ordered, func(i, j int) bool { return ordered[i].Stage < ordered[j].Stage })

	res := &Result{}
	seen := map[string]bool{}
	for _, l := range ordered {
		if l.ID == "" {
			return nil, fmt.Errorf("layer %q has no ID", l.Name)
		}
		if seen[l.ID] {
			return nil, fmt.Errorf("duplicate layer ID %q", l.ID)
		}
		seen[l.ID] = true
		if !l.Enabled {
			continue
		}
		if len(l.Override) > 0 {
			p, err := Parse(l.Override)
			if err != nil {
				return nil, fmt.Errorf("layer %s: %w", l.ID, err)
			}
			if err := Merge(root, p); err != nil {
				return nil, fmt.Errorf("layer %s: %w", l.ID, err)
			}
		}
		if l.Transform != nil {
			w, err := l.Transform(root)
			if err != nil {
				return nil, fmt.Errorf("layer %s: %w", l.ID, err)
			}
			for _, s := range w {
				res.Warnings = append(res.Warnings, l.ID+": "+s)
			}
		}
		res.Applied = append(res.Applied, l.ID)
	}
	dedupe(root)
	sinkData(root)
	res.Config, err = Encode(root)
	if err != nil {
		return nil, err
	}
	return res, nil
}

// dedupePaths are lists where a repeated scalar has no effect: rules match
// first-wins, the others are sets. Layers that append to them (e.g. the
// Tailscale layer adding "+.ts.net" to a filter that already has it) would
// otherwise leave noise in the output.
var dedupePaths = [][]string{
	{"rules"},
	{"dns", "fake-ip-filter"},
	{"tun", "route-exclude-address"},
	{"tun", "route-include-address"},
}

func dedupe(root *yaml.Node) {
	for _, p := range dedupePaths {
		seq := lookupPath(root, p...)
		if seq == nil || seq.Kind != yaml.SequenceNode {
			continue
		}
		seen := map[string]bool{}
		out := seq.Content[:0]
		for _, it := range seq.Content {
			if it.Kind == yaml.ScalarNode {
				if seen[it.Value] {
					continue
				}
				seen[it.Value] = true
			}
			out = append(out, it)
		}
		seq.Content = out
	}
}

// dataKeys are the large data sections of a config. sinkData moves them to
// the end, keeping their order, so settings added by layers stay at the top
// where people look for them.
var dataKeys = map[string]bool{
	"proxies": true, "proxy-providers": true, "proxy-groups": true,
	"rule-providers": true, "sub-rules": true, "rules": true,
}

func sinkData(root *yaml.Node) {
	var head, tail []*yaml.Node
	for i := 0; i+1 < len(root.Content); i += 2 {
		if dataKeys[root.Content[i].Value] {
			tail = append(tail, root.Content[i], root.Content[i+1])
		} else {
			head = append(head, root.Content[i], root.Content[i+1])
		}
	}
	root.Content = append(head, tail...)
}

// OverrideLayer is a convenience constructor for a static YAML layer.
func OverrideLayer(id, name string, kind Kind, stage Stage, override []byte) Layer {
	return Layer{ID: id, Name: name, Kind: kind, Stage: stage, Enabled: true, Override: override}
}
